    }

    Write-Host "`n      Ledger Entries:" -ForegroundColor Cyan
    foreach ($le in $entries.entries) {
        $color = if ($le.entry_type -eq "debit") { "Green" } else { "Red" }
        Write-Host "        [$($le.entry_type.ToUpper())] $($le.account_id) amount=`$$($le.amount) balance_after=`$$($le.balance_after)" -ForegroundColor $color
    }
} catch {
