    "12. Merchant full flow -> ledger auto-update",
    "13. Customer full flow -> ledger auto-update"
) | ForEach-Object { Write-Host "    . $_" -ForegroundColor White }

Write-Host ""
if ($script:fail -eq 0) {
    Write-Host "  [OK] ALL LEDGER TESTS PASSED!"        -ForegroundColor Green
    Write-Host "  [OK] Every dollar is tracked!"        -ForegroundColor Green
    Write-Host "  [OK] Double-entry bookkeeping works!" -ForegroundColor Green
    Write-Host "  [OK] Merchant balances updating!"     -ForegroundColor Green
    Write-Host "  [OK] Platform fees being collected!"  -ForegroundColor Green
} else {
    Write-Host "  [!!] $($script:fail) TEST(S) FAILED" -ForegroundColor Yellow
    Write-Host "`n  Common fixes:" -ForegroundColor Yellow
    Write-Host "    Fraud velocity : docker exec postgres psql -U payments -d fraud_db -c 'TRUNCATE fraud_checks, ml_training_samples CASCADE;'" -ForegroundColor Gray
    Write-Host "    Ledger logs    : docker compose logs --tail=30 ledger-service"   -ForegroundColor Gray
    Write-Host "    Payment logs   : docker compose logs --tail=30 payment-service"  -ForegroundColor Gray
    Write-Host "    Gateway logs   : docker compose logs --tail=30 gateway"          -ForegroundColor Gray
}
Write-Host ""
